import React, { useState, useEffect } from 'react';
import axios from 'axios';

const PublicForm: React.FC = () => {
  const [formData, setFormData] = useState({
    full_name: '',
    employee_code: '',
    employment_status: 'شاغل'
  });
  const [products, setProducts] = useState([]);
  const [requestItems, setRequestItems] = useState({});
  const [deadline, setDeadline] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [submitted, setSubmitted] = useState(false);
  const [existingRequest, setExistingRequest] = useState(null);

  // Load products and deadline
  useEffect(() => {
    const fetchData = async () => {
      try {
        const productsRes = await axios.get('/api/products/public');
        setProducts(productsRes.data);
        
        const deadlineRes = await axios.get('/api/settings/deadline');
        setDeadline(deadlineRes.data.edit_deadline);
      } catch (error) {
        console.error('Error loading data:', error);
      }
    };
    fetchData();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    try {
      const items = products.map(p => ({
        product_id: p.id,
        quantity: parseInt(requestItems[p.id] || 0)
      }));

      const payload = {
        ...formData,
        items: items
      };

      const response = await axios.post('/api/requests', payload);
      setMessage('✅ درخواست شما با موفقیت ثبت شد!');
      setSubmitted(true);
      setExistingRequest(response.data);
    } catch (error) {
      setMessage('❌ خطا: ' + (error.response?.data?.detail || 'خطای ناشناخته'));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 py-8 px-4">
      <div className="max-w-4xl mx-auto bg-white rounded-lg shadow-lg p-6">
        <h1 className="text-3xl font-bold text-center text-blue-600 mb-6">
          فرم ثبت درخواست
        </h1>
        
        {deadline && (
          <div className="bg-blue-50 border border-blue-200 text-blue-700 px-4 py-2 rounded mb-4 text-center">
            ⏰ آخرین مهلت ویرایش: {new Date(deadline).toLocaleDateString('fa-IR')}
          </div>
        )}

        <form onSubmit={handleSubmit}>
          {/* User Info */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                نام و نام خانوادگی
              </label>
              <input
                type="text"
                required
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                value={formData.full_name}
                onChange={(e) => setFormData({...formData, full_name: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                کد پرسنلی
              </label>
              <input
                type="text"
                required
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                value={formData.employee_code}
                onChange={(e) => setFormData({...formData, employee_code: e.target.value})}
              />
            </div>
          </div>

          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-2">
              وضعیت اشتغال
            </label>
            <div className="flex gap-4">
              <label className="inline-flex items-center">
                <input
                  type="radio"
                  value="شاغل"
                  checked={formData.employment_status === 'شاغل'}
                  onChange={(e) => setFormData({...formData, employment_status: e.target.value})}
                  className="form-radio"
                />
                <span className="mr-2">شاغل</span>
              </label>
              <label className="inline-flex items-center">
                <input
                  type="radio"
                  value="بازنشسته"
                  checked={formData.employment_status === 'بازنشسته'}
                  onChange={(e) => setFormData({...formData, employment_status: e.target.value})}
                  className="form-radio"
                />
                <span className="mr-2">بازنشسته</span>
              </label>
            </div>
          </div>

          {/* Products */}
          <div className="mb-6">
            <h2 className="text-xl font-semibold text-gray-800 mb-3">محصولات</h2>
            {products.map((product) => (
              <div key={product.id} className="flex items-center gap-4 p-3 border rounded-md mb-2">
                <div className="flex-1">
                  <span className="font-medium">{product.name}</span>
                  <span className="text-sm text-gray-500 mr-2">({product.type})</span>
                  <span className="text-sm text-gray-400 mr-2">حداکثر: {product.max_quantity}</span>
                </div>
                <div>
                  <input
                    type="number"
                    min="0"
                    max={product.max_quantity}
                    className="w-20 px-2 py-1 border border-gray-300 rounded-md"
                    value={requestItems[product.id] || 0}
                    onChange={(e) => {
                      const val = parseInt(e.target.value) || 0;
                      setRequestItems({
                        ...requestItems,
                        [product.id]: Math.min(val, product.max_quantity)
                      });
                    }}
                  />
                </div>
              </div>
            ))}
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 transition disabled:opacity-50"
          >
            {loading ? 'در حال ارسال...' : 'ثبت درخواست'}
          </button>
        </form>

        {message && (
          <div className={`mt-4 p-3 rounded-md ${message.includes('✅') ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
            {message}
          </div>
        )}
      </div>
    </div>
  );
};

export default PublicForm;
